tinymce.PluginManager.add("dotCustomButtons", function (editor) {

    editor.ui.registry.addButton("dotAddImage", {
        icon: "image",
        // Found in manual QA: `editor.settings` no longer exists in TinyMCE 8. `editor.options.get()`
        // looked like the replacement but only returns a value for options registered via
        // `editor.options.register()` — arbitrary custom init keys like this one just aren't tracked
        // there. `editor.getParam(name, default)` (still present in 8.x) is the one that reads
        // straight from the raw init object regardless of registration, same as the old 4.x usage.
        tooltip: editor.getParam("dotLanguageStrings", {})["insertImageLabel"],
        onAction: function () {
            // TinyMCE 8's `onAction` gets the toolbar button's own API object, not the DOM click
            // event the TinyMCE 4 `onclick` handler used to receive — `editor.getContainer()` is
            // the editor's own wrapping element, which the JSP markup nests inside
            // `.wysiwyg-container`, giving the same ancestor the old `event.target` walk reached.
            var editorContainer = editor.getContainer();
            var wysiwygContainer = editorContainer ? editorContainer.closest(".wysiwyg-container") : null;

            if (!wysiwygContainer) {
                return;
            }

            cmsFileBrowserImage.selectFolder = wysiwygContainer.dataset.selectFolder
                                                    .split(",")
                                                    .map(function (path) {return path.trim()});
            cmsFileBrowserImage.show();
        },
    });
});
